package com.ruoyi.system.messaging;
import com.ruoyi.common.core.messaging.QueueKind;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.util.*;import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;import static com.ruoyi.system.messaging.QueueControlStore.*;
class QueueControlStoreTest {
 QueueControlStore store;
 @BeforeEach void setup(){String url=System.getenv("QUEUE_CONTROL_TEST_URL");Assumptions.assumeTrue(url!=null&&url.contains("/queue_control_test?"));store=new QueueControlStore();store.db=new JdbcTemplate(new DriverManagerDataSource(url,"root",System.getenv("INVENTORY_TEST_PASSWORD")));for(String table:Arrays.asList("sys_mq_dead_review","sys_mq_dead_letter","sys_mq_operation","sys_mq_instance","sys_mq_rate_slot","sys_mq_queue_snapshot","sys_mq_alert_event","sys_mq_alert"))store.db.update("DELETE FROM "+table);store.db.update("UPDATE sys_mq_queue_policy SET desired_mode='RUNNING',concurrency=IF(business_type IN ('PRODUCT_BIND','REFUND_PULL','REFUND_CONVERT','EXCHANGE_PULL','EXCHANGE_CONVERT'),1,2),prefetch=IF(business_type='SALES_DOCUMENT',5,1),revision=1");}
 Map<String,Object> change(String type,String mode){Map<String,Object> r=store.policy(QueueKind.of(type));r.put("desired_mode",mode);r.put("reason","test");return r;}
 Map<String,Object> node(String type,int version,String state,int count,int active){Map<String,Object> r=new LinkedHashMap<>();r.put("business_type",type);r.put("applied_version",version);r.put("state",state);r.put("actual_consumers",count);r.put("active_work",active);return r;}
 void beat(String instance,Map<String,Object> node){Map<String,Object> r=new LinkedHashMap<>();r.put("service","channel");r.put("instance",instance);r.put("queues",Collections.singletonList(node));store.heartbeat(r);}
 @Test void revisionsPreventLostUpdatesAndAuditTheExactPolicy(){Map<String,Object> first=change("PRODUCT_PULL","PAUSED");store.save("PRODUCT_PULL",first,"admin");assertThrows(IllegalArgumentException.class,()->store.save("PRODUCT_PULL",first,"admin"));assertEquals(1,store.db.queryForObject("SELECT COUNT(*) FROM sys_mq_operation",Integer.class));assertEquals(2,n(store.policy(QueueKind.PRODUCT_PULL),"revision"));}
 @Test void independentQueueParametersAreBoundedByPerServiceBudget(){Map<String,Object> p=change("PRODUCT_PULL","RUNNING");p.put("concurrency",8);store.save("PRODUCT_PULL",p,"admin");p=change("PRODUCT_BIND","RUNNING");p.put("concurrency",8);Map<String,Object> rejected=p;assertThrows(IllegalArgumentException.class,()->store.save("PRODUCT_BIND",rejected,"admin"));p=change("PRODUCT_PULL","RUNNING");p.put("prefetch",0);Map<String,Object> invalid=p;assertThrows(IllegalArgumentException.class,()->store.save("PRODUCT_PULL",invalid,"admin"));}
 @Test void pausedIsConfirmedOnlyAfterAllInstancesDrainAndApply(){store.snapshot("channel","node:one");store.snapshot("channel","node:two");store.save("PRODUCT_PULL",change("PRODUCT_PULL","PAUSED"),"admin");beat("node:one",node("PRODUCT_PULL",2,"PAUSED",0,0));beat("node:two",node("PRODUCT_PULL",1,"RUNNING",2,1));assertEquals("PAUSING",store.detail("PRODUCT_PULL",false).get("effective_state"));beat("node:two",node("PRODUCT_PULL",2,"PAUSED",0,1));assertEquals("PAUSING",store.detail("PRODUCT_PULL",false).get("effective_state"));beat("node:two",node("PRODUCT_PULL",2,"PAUSED",0,0));assertEquals("PAUSED",store.detail("PRODUCT_PULL",false).get("effective_state"));}
 @Test void restartUsesPersistedPauseAndRetiredSessionsDoNotBlockNewInstance(){store.snapshot("channel","old");beat("old",node("PRODUCT_PULL",1,"STOPPED",0,0));store.save("PRODUCT_PULL",change("PRODUCT_PULL","PAUSED"),"admin");assertEquals("PAUSED",s(store.snapshot("channel","new").get(0),"desired_mode"));beat("new",node("PRODUCT_PULL",2,"PAUSED",0,0));assertEquals("PAUSED",store.detail("PRODUCT_PULL",false).get("effective_state"));}
 @Test void staleInstanceCannotBeMistakenForSuccessfullyPaused(){store.snapshot("channel","old");store.save("PRODUCT_PULL",change("PRODUCT_PULL","PAUSED"),"admin");beat("old",node("PRODUCT_PULL",2,"PAUSED",0,0));store.db.update("UPDATE sys_mq_instance SET last_seen=DATE_SUB(NOW(),INTERVAL 40 SECOND)");assertEquals("PAUSING",store.detail("PRODUCT_PULL",false).get("effective_state"));}
 @Test void heartbeatCannotControlOtherServicesOrInventTopology(){Map<String,Object> body=new LinkedHashMap<>();body.put("service","channel");body.put("instance","one");body.put("queues",Collections.singletonList(node("SALES_DOCUMENT",1,"RUNNING",1,0)));assertThrows(IllegalArgumentException.class,()->store.heartbeat(body));assertThrows(IllegalArgumentException.class,()->store.snapshot("unknown","one"));assertThrows(IllegalArgumentException.class,()->QueueKind.of("arbitrary"));}
 @Test void platformRateBudgetIsSharedBetweenDifferentInstances(){List<String> keys=Arrays.asList(String.join("",Collections.nCopies(64,"a")),String.join("",Collections.nCopies(64,"b")));assertTrue(store.rate("channel","one","PRODUCT_PULL",keys));assertFalse(store.rate("channel","two","PRODUCT_PULL",keys));store.save("PRODUCT_PULL",change("PRODUCT_PULL","PAUSED"),"admin");store.db.update("UPDATE sys_mq_rate_slot SET next_at=DATE_SUB(NOW(),INTERVAL 1 SECOND)");assertFalse(store.rate("channel","one","PRODUCT_PULL",keys));}
 @Test void brokerDataIsNotReplacedWithZeroWhenMonitoringFails(){store.db.update("INSERT INTO sys_mq_queue_snapshot(business_type,payload_json,sampled_at,last_error) VALUES ('PRODUCT_PULL','{\"ready\":7}',DATE_SUB(NOW(),INTERVAL 60 SECOND),'monitor down')");Map<?,?> broker=(Map<?,?>)store.detail("PRODUCT_PULL",false).get("broker");assertEquals(false,broker.get("fresh"));assertEquals(7,((Map<?,?>)broker.get("data")).get("ready"));}
 @Test void alertsRequireSustainedFailureAndRecordRecovery(){QueueMonitor monitor=new QueueMonitor();monitor.store=store;monitor.alert("PRODUCT_PULL","TEST",true,"test",60);assertEquals("PENDING",store.db.queryForObject("SELECT state FROM sys_mq_alert",String.class));monitor.alert("PRODUCT_PULL","TEST",true,"test",60);assertEquals("PENDING",store.db.queryForObject("SELECT state FROM sys_mq_alert",String.class));store.db.update("UPDATE sys_mq_alert SET first_seen=DATE_SUB(NOW(),INTERVAL 61 SECOND)");monitor.alert("PRODUCT_PULL","TEST",true,"test",60);assertEquals("FIRING",store.db.queryForObject("SELECT state FROM sys_mq_alert",String.class));monitor.alert("PRODUCT_PULL","TEST",false,"test",60);assertEquals("RECOVERED",store.db.queryForObject("SELECT state FROM sys_mq_alert",String.class));monitor.alert("PRODUCT_PULL","TEST",true,"test",60);assertEquals("PENDING",store.db.queryForObject("SELECT state FROM sys_mq_alert",String.class));assertTrue(store.db.queryForObject("SELECT TIMESTAMPDIFF(SECOND,first_seen,NOW()) FROM sys_mq_alert",Integer.class)<2);}
 @Test void globalPauseIncludesInstancesBeyondTheDisplayedHundredRows(){store.save("PRODUCT_PULL",change("PRODUCT_PULL","PAUSED"),"admin");List<Object[]> rows=new ArrayList<>();for(int i=0;i<100;i++)rows.add(new Object[]{"PRODUCT_PULL","node:"+i,"channel",2,"PAUSED"});store.db.batchUpdate("INSERT INTO sys_mq_instance(business_type,instance_id,service_code,applied_version,state) VALUES (?,?,?,?,?)",rows);beat("older",node("PRODUCT_PULL",1,"RUNNING",2,0));store.db.update("UPDATE sys_mq_instance SET last_seen=DATE_SUB(NOW(),INTERVAL 2 SECOND) WHERE instance_id='older'");Map<String,Object> detail=store.detail("PRODUCT_PULL",false);assertEquals(101,n(detail,"instance_count"));assertEquals(100,((List<?>)detail.get("instances")).size());assertEquals("PAUSING",s(detail,"effective_state"));}
 @Test void companyUsersCannotAccessSharedQueueMetricsEvenWithAControllerReference(){com.ruoyi.common.core.context.SecurityContextHolder.setUserId("2");try{com.ruoyi.system.controller.QueueControlController controller=new com.ruoyi.system.controller.QueueControlController();assertThrows(IllegalArgumentException.class,controller::list);assertThrows(IllegalArgumentException.class,()->controller.detail("PRODUCT_PULL"));}finally{com.ruoyi.common.core.context.SecurityContextHolder.remove();}}
 @Test void productAndExchangePullShareApplicationAndShopSlotsAcrossServices(){List<String> keys=Arrays.asList(String.join("",Collections.nCopies(64,"c")),String.join("",Collections.nCopies(64,"d")));assertTrue(store.rate("channel","channel-one","PRODUCT_PULL",keys));assertFalse(store.rate("order","order-one","EXCHANGE_PULL",keys));store.db.update("UPDATE sys_mq_rate_slot SET next_at=DATE_SUB(NOW(),INTERVAL 1 SECOND)");assertTrue(store.rate("order","order-two","EXCHANGE_PULL",keys));assertFalse(store.rate("channel","channel-two","PRODUCT_PULL",keys));assertThrows(IllegalArgumentException.class,()->store.rate("channel","spoof","EXCHANGE_PULL",keys));}
}
